#!/usr/bin/env python3
"""Regenerate the .bsp reader test fixture: lit_room.map, lit_room.bsp, expected.json.

Writes a sealed room with a pillar, two colored lights, and a flickering light
(style 10) that overlaps them so some faces carry two light styles. Compiles it
with the pinned ericw-tools through tools/compile.py, keeps the .bsp, and
records what tools/bspdump.py reads from it: entities, models, and per face the
texture, vertices, light styles, lightmap offset and size, and first luxel.
The web .bsp reader must read the same values.

Run after changing the room or bumping ericw-tools:
    python web/tests/fixtures/bsp/generate.py
"""

from __future__ import annotations

import json
import shutil
import struct
import sys
import tempfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
REPO_ROOT = HERE.parents[3]
sys.path.insert(0, str(REPO_ROOT / "tools"))
from bspdump import NO_STYLE, Bsp, LUXEL_SIZE, lightmap_size, parse_entities  # noqa: E402
from compile import compile_map  # noqa: E402

Vec = tuple[float, float, float]

# (mins, maxs, texture) per brush: floor, ceiling, four walls, and a pillar.
BRUSHES: list[tuple[Vec, Vec, str]] = [
    ((-208, -144, -16), (208, 144, 0), "dev/grid_grey"),
    ((-208, -144, 160), (208, 144, 176), "dev/grid_dark"),
    ((-208, -144, 0), (-192, 144, 160), "dev/grid_light"),
    ((192, -144, 0), (208, 144, 160), "dev/grid_light"),
    ((-192, -144, 0), (192, -128, 160), "dev/grid_light"),
    ((-192, 128, 0), (192, 144, 160), "dev/grid_light"),
    ((-32, -32, 0), (32, 32, 112), "dev/grid_orange"),
]

LIGHTS = [
    {"origin": "-128 -64 96", "light": "200", "_color": "1 0.4 0.3"},
    {"origin": "128 64 96", "light": "200", "_color": "0.3 0.5 1"},
    {"origin": "-160 -104 32", "light": "80", "style": "10"},
]


def texture_axes(normal: Vec) -> str:
    """Valve 220 texture axes for an axis-aligned face, as TrenchBroom would write them."""
    if normal[2]:
        return "[ 1 0 0 0 ] [ 0 -1 0 0 ]"
    if normal[0]:
        return "[ 0 1 0 0 ] [ 0 0 -1 0 ]"
    return "[ 1 0 0 0 ] [ 0 0 -1 0 ]"


def box_text(mins: Vec, maxs: Vec, texture: str) -> str:
    """A box brush as six faces, each given by three points wound so the plane faces outward."""
    lines = []
    for axis in range(3):
        for side, bound in ((-1, mins), (1, maxs)):
            u, v = (axis + 1) % 3, (axis + 2) % 3
            points = []
            for du, dv in ((0, 0), (1, 0), (0, 1)) if side > 0 else ((0, 0), (0, 1), (1, 0)):
                p = [0.0, 0.0, 0.0]
                p[axis] = bound[axis]
                p[u] = mins[u] + du * (maxs[u] - mins[u])
                p[v] = mins[v] + dv * (maxs[v] - mins[v])
                points.append(p)
            # Quake's plane normal is (p0 - p1) x (p2 - p1); swap two points if it faces inward.
            a = [points[0][i] - points[1][i] for i in range(3)]
            b = [points[2][i] - points[1][i] for i in range(3)]
            n = [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]
            if n[axis] * side < 0:
                points[0], points[2] = points[2], points[0]
            normal = tuple(float(side) if i == axis else 0.0 for i in range(3))
            pts = " ".join("( %g %g %g )" % tuple(p) for p in points)
            lines.append(f"{pts} {texture} {texture_axes(normal)} 0 1 1 0 0 0")
    return "{\n" + "\n".join(lines) + "\n}"


def write_map(path: Path) -> None:
    parts = ["// Game: Hollow Coil", "// Format: Quake2 (Valve)",
             "// .bsp reader test fixture. Generated by generate.py; do not edit by hand.",
             "{", '"classname" "worldspawn"', '"mapversion" "220"']
    parts += [box_text(mn, mx, tex) for mn, mx, tex in BRUSHES]
    parts.append("}")
    parts += ["{", '"classname" "info_player_start"', '"origin" "-160 0 25"', '"angle" "0"', "}"]
    for light in LIGHTS:
        parts += ["{", '"classname" "light"', *(f'"{k}" "{v}"' for k, v in light.items()), "}"]
    parts += ["{", '"classname" "info_marker"', '"name" "corner"', '"origin" "160 96 25"', "}"]
    path.write_text("\n".join(parts) + "\n", encoding="utf-8", newline="\n")


def expected_values(bsp: Bsp) -> dict:
    texinfos = bsp.texinfos()
    planes = bsp.lump("planes")
    faces = bsp.lump("faces")
    lighting = bsp.lump("lighting")
    out_faces = []
    for i in range(0, len(faces), 20):
        plane, side, first_edge, num_edges, texinfo = struct.unpack_from("<HhihH", faces, i)
        styles = [s for s in faces[i + 12 : i + 16] if s != NO_STYLE]
        (light_offset,) = struct.unpack_from("<i", faces, i + 16)
        s_axis, t_axis, flags, name = texinfos[texinfo]
        points = bsp.face_vertices(first_edge, num_edges)
        normal = struct.unpack_from("<3f", planes, plane * 20)
        if side:
            normal = tuple(-c for c in normal)
        face = {
            "texture": name,
            "flags": flags,
            "normal": [round(c, 6) + 0.0 for c in normal],
            "vertices": [[round(c, 4) for c in p] for p in points],
            "styles": styles,
            "light_offset": light_offset,
        }
        if light_offset >= 0 and styles:
            width, height = lightmap_size(points, s_axis, t_axis)
            mins = [min(p[0] * a[0] + p[1] * a[1] + p[2] * a[2] + a[3] for p in points) for a in (s_axis, t_axis)]
            face["lightmap"] = {
                "mins": [(int(m // LUXEL_SIZE)) * LUXEL_SIZE for m in mins],
                "width": width,
                "height": height,
                "first_luxel": list(lighting[light_offset : light_offset + 3]),
            }
        out_faces.append(face)
    models = bsp.lump("models")
    return {
        "lighting_bytes": len(lighting),
        "entities": parse_entities(bsp.lump("entities").split(b"\0")[0].decode("utf-8")),
        "models": [dict(zip(("first_face", "num_faces"), struct.unpack_from("<ii", models, i + 40)))
                   for i in range(0, len(models), 48)],
        "faces": out_faces,
    }


def main() -> int:
    map_path = HERE / "lit_room.map"
    write_map(map_path)
    with tempfile.TemporaryDirectory() as tmp:
        result = compile_map(map_path, out_dir=Path(tmp))
        if not result.ok:
            raise SystemExit("compile failed:\n  " + "\n  ".join(result.problems))
        shutil.copyfile(Path(tmp) / "lit_room.bsp", HERE / "lit_room.bsp")
    expected = expected_values(Bsp((HERE / "lit_room.bsp").read_bytes()))
    if not any(len(f["styles"]) > 1 for f in expected["faces"]):
        raise SystemExit("no face has more than one light style; move the flickering light")
    (HERE / "expected.json").write_text(json.dumps(expected, indent=1) + "\n", encoding="utf-8", newline="\n")
    lit = sum(1 for f in expected["faces"] if "lightmap" in f)
    multi = sum(1 for f in expected["faces"] if len(f["styles"]) > 1)
    print(f"wrote lit_room.map, lit_room.bsp, expected.json ({len(expected['faces'])} faces, {lit} lit, {multi} with two styles)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
